import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"D0.2 · 可点击的端到端产品原型","description":"Hearth D0.2 开发增量：一个覆盖四个入口与七种任务状态、在桌面和手机宽度都能走通的端到端原型。","frontmatter":{"title":"D0.2 · 可点击的端到端产品原型","description":"Hearth D0.2 开发增量：一个覆盖四个入口与七种任务状态、在桌面和手机宽度都能走通的端到端原型。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-0/d0-2.md","filePath":"delivery/stage-0/d0-2.md","lastUpdated":1793797632000}'),s={name:"delivery/stage-0/d0-2.md"};function r(h,a,d,o,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 0 · D0.2 · 2 / 4</p><h1 id="d0-2-·-可点击的端到端产品原型" tabindex="-1">D0.2 · 可点击的端到端产品原型 <a class="header-anchor" href="#d0-2-·-可点击的端到端产品原型" aria-label="Permalink to &quot;D0.2 · 可点击的端到端产品原型&quot;">​</a></h1><p class="lead">在写真实执行内核之前，先用可点击原型证明用户能完成一条完整任务路径，并且异常状态也有明确的下一步。</p><p class="page-meta">STAGE 0 · D0.2 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>一个覆盖四个入口与七种任务状态、在桌面和手机宽度都能走通的端到端原型。</div><div><strong>完成门槛</strong>新用户不看说明也能完成主要路径；每个状态只有一个主动作；没有内部术语；失败状态给出下一步；原型状态可映射到真实投影字段。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>一个覆盖四个入口与七种任务状态、在桌面和手机宽度都能走通的端到端原型。</p><p>Stage 0 的产出是产品真相与实现契约。没有真实任务、可点击原型和可重复评测，后续开发会把假设当成事实。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>一个空仓库、可记录的真实工作样本，以及一位愿意持续反馈的首位用户。</li><li>允许观察全人工流程与直接使用 Codex 的基线，不要求系统已经存在。</li><li>本阶段不接入真实发送、支付、删除或系统设置修改。</li><li>D0.1 的交付物已经验收；未通过时不进入本增量。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-四个入口与信息架构" tabindex="-1">01 · 四个入口与信息架构 <a class="header-anchor" href="#_01-·-四个入口与信息架构" aria-label="Permalink to &quot;01 · 四个入口与信息架构&quot;">​</a></h3><p>今日展示正在运行和最近完成；需要你只放审批、补充信息和接管；产物按任务聚合可预览文件；设置承载工作区、连接和通知。用户进入后先看到“现在需要做什么”，而不是系统能力清单。</p><h3 id="_02-·-七种状态与唯一主动作" tabindex="-1">02 · 七种状态与唯一主动作 <a class="header-anchor" href="#_02-·-七种状态与唯一主动作" aria-label="Permalink to &quot;02 · 七种状态与唯一主动作&quot;">​</a></h3><p>为排队、执行、等待审批、需要信息、完成、失败、可恢复分别定义原因、下一步和一个主按钮。取消、重试、查看原始事件等次要动作收进详情，避免同一状态出现多个互相竞争的主按钮。</p><h3 id="_03-·-完整任务剧本" tabindex="-1">03 · 完整任务剧本 <a class="header-anchor" href="#_03-·-完整任务剧本" aria-label="Permalink to &quot;03 · 完整任务剧本&quot;">​</a></h3><p>用接近真实的数据串起创建任务、看到计划与进度、处理审批或补充信息、打开产物、制造一次失败、选择恢复的完整路径。原型必须包含至少一个无法自动恢复、需要转人工的路径。</p><h3 id="_04-·-可用性走查与投影映射" tabindex="-1">04 · 可用性走查与投影映射 <a class="header-anchor" href="#_04-·-可用性走查与投影映射" aria-label="Permalink to &quot;04 · 可用性走查与投影映射&quot;">​</a></h3><p>让首位用户不看说明完成任务，记录首次成功时间、犹豫点和错误点击；同时维护“状态—主动作—projection 字段”映射表，原型里每个可见字段都必须能指向真实契约。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>packages/core/src/schema</code> — 领域实体、状态机与失败分类</li><li><code>packages/eventlog</code> — Event Log、投影与 migration</li><li><code>packages/evals</code> — 任务集、runner、评分与人工复核</li><li><code>apps/web</code> — 今日、需要你、产物、设置与任务详情原型</li><li><code>fixtures/tasks</code> — 真实任务样本与失败样本</li><li><code>docs/adr</code> — Build vs Integrate、事件模型与前端投影决策</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>Event</code></td><td>id、type、schemaVersion、occurredAt、actor、subject、causationId、correlationId、payload；只追加，不能覆盖历史。</td></tr><tr><td><code>TaskCardProjection</code></td><td>taskId、title、state、primaryAction、reason、lastEventAt、artifacts、budget；页面不读取数据库字段。</td></tr><tr><td><code>ExecutorEvent</code></td><td>标准化事件、产物引用、structResult、validation、failureClass、recoverable；执行器不直接写主库。</td></tr><tr><td><code>Approval</code></td><td>effectPreview、scope、expiresAt、decision、idempotencyKey；审批绑定真实动作和参数。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:smoke：12</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 个任务可重复跑分</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev：打开桌面与</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 390px</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 手机宽度原型</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-0/d0-2.html">D0.2 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：四个入口与信息架构、七种状态与唯一主动作、完整任务剧本、可用性走查与投影映射。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“原型状态无法映射”。页面必须显示“页面显示“需要处理”，并记录未识别的 projection 字段和任务 ID。”，然后按“补齐状态映射、更新契约测试，再重新演示原路径。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：新用户不看说明也能完成主要路径；每个状态只有一个主动作；没有内部术语；失败状态给出下一步；原型状态可映射到真实投影字段。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>可点击原型与走查脚本</li><li>状态-主动作-投影字段映射表</li><li>桌面与手机截图</li><li>可用性观察记录</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 新用户不看说明也能完成主要路径；每个状态只有一个主动作；没有内部术语；失败状态给出下一步；原型状态可映射到真实投影字段。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>原型状态无法映射</td><td>页面显示“需要处理”，并记录未识别的 projection 字段和任务 ID。</td><td>补齐状态映射、更新契约测试，再重新演示原路径。</td></tr><tr><td>真实任务无法验收</td><td>任务保留在候选池，标注原因，不进入开发承诺。</td><td>补清输入、产物或验收方式，或换一个真实任务。</td></tr><tr><td>基线不可比较</td><td>该任务不进入评测集，避免用失真的数据证明价值。</td><td>重新记录人工分钟、成功率、Token 与失败类型。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不先做完整内核再补界面。</li><li>不用文档完成度替代可点击原型与可重复评测。</li><li>不接入真实高风险外部副作用。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/design/">项目设计与取舍</a></li><li><a href="/hearth-os/reference/checklists.html">默认清单</a></li><li><a href="/hearth-os/architecture/domain-model.html">领域模型与协议</a></li><li><a href="/hearth-os/architecture/evaluation.html">评估体系</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-0/d0-3.html">D0.3 · 协议、状态机与 UI 数据契约</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const u=e(s,[["render",r]]);export{k as __pageData,u as default};
